import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>JPG না PNG — স্বচ্ছতার ক্ষেত্রে দুটির মধ্যে অনেক পার্থক্য৤ একটি স্বচ্ছতা দিতে পারে, আরেকটি পারে না৤ এই পার্থক্য না জানলে লোগো, স্টিকার আর ওয়াটারমার্কে ভুল হয়৤</p>\n<p>এই তুলনায় আপনি জানবেন স্বচ্ছতা কী, কখন এটি গুরুত্বপূর্ণ, আর কোন ফরম্যাট কখন ব্যবহার করবেন৤</p>\n<p>সবচেয়ে গুরুত্বপূর্ণ বিষয়টি হলো, JPG থেকে PNG-তে কনভার্ট করলে স্বচ্ছতা তৈরি হয় না৤</p>\n<h2 id=\"jpg-at-a-glance\">JPG এক নজরে</h2>\n<p>JPG সবচেয়ে পরিচিত ফরম্যাট৤ ছবির জন্য এটি সবচেয়ে বেশি ব্যবহৃত হয়৤</p>\n<p>JPG ক্ষতিকর ফরম্যাট৤ কিছু তথ্য ফেলে দিয়ে ফাইল ছোট করে৤</p>\n<p>JPG স্বচ্ছতা দিতে পারে না৤ প্রতিটি পিক্সেলে রং থাকতে হয়৤</p>\n<h2 id=\"png-at-a-glance\">PNG এক নজরে</h2>\n<p>PNG ক্ষতিহীন ফরম্যাট৤ কোনো তথ্য ফেলে না৤</p>\n<p>PNG স্বচ্ছতা দিতে পারে৤ প্রতিটি পিক্সেলে স্বচ্ছতার তথ্য থাকে৤</p>\n<p>PNG ফাইল JPG-এর চেয়ে বড় হয়৤ তবে লোগো আর লেখার জন্য এটি সেরা৤</p>\n<h2 id=\"what-transparency-is\">স্বচ্ছতা কী</h2>\n<p>স্বচ্ছতা মানে ছবির কিছু অংশ দেখা যায় না৤ পেছনের ব্যাকগ্রাউন্ড দেখা যায়৤</p>\n<p>লোগোতে স্বচ্ছতা দরকার হয়৤ লোগো যেকোনো ব্যাকগ্রাউন্ডে বসানো যায়৤</p>\n<p>স্বচ্ছতা আলফা চ্যানেলে সংরক্ষণ হয়৤ প্রতিটি পিক্সেলে কতটা স্বচ্ছ, তা লেখা থাকে৤</p>\n<h2 id=\"when-transparency-matters\">কখন স্বচ্ছতা গুরুত্বপূর্ণ</h2>\n<p>লোগোতে স্বচ্ছতা গুরুত্বপূর্ণ৤ লোগো বিভিন্ন রঙের ব্যাকগ্রাউন্ডে বসানো হয়৤</p>\n<p>আইকনেও স্বচ্ছতা দরকার৤ আইকন যেকোনো জায়গায় বসানো যায়৤</p>\n<p>স্টিকার আর ওয়াটারমার্কেও স্বচ্ছতা দরকার৤ এতে মূল ছবি ঢাকা পড়ে না৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবি যেকোনো ব্যাকগ্রাউন্ডের উপর বসবে৤ লোগো ওয়েবসাইটের হেডারে বসলে ব্যাকগ্রাউন্ডের রং বদলাতে পারে৤ স্বচ্ছ লোগো সব ব্যাকগ্রাউন্ডে মানায়৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবির উপর ছবি বসানো হবে৤ স্টিকার চ্যাটে পাঠালে স্বচ্ছ স্টিকার সুন্দর দেখায়৤ সাদা বাক্সসহ স্টিকার খারাপ দেখায়৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবিটি ওয়াটারমার্ক হিসেবে ব্যবহার হবে৤ স্বচ্ছ ওয়াটারমার্ক ছবির উপর হালকাভাবে বসে৤ সাদা ব্যাকগ্রাউন্ডের ওয়াটারমার্ক ছবি ঢেকে দেয়৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন আইকন অ্যাপে ব্যবহার হবে৤ অ্যাপের আইকন বিভিন্ন রঙের ব্যাকগ্রাউন্ডে দেখায়৤ স্বচ্ছ আইকন সব জায়গায় মানায়৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবিটি প্রেজেন্টেশনে ব্যবহার হবে৤ স্লাইডের ব্যাকগ্রাউন্ডের রং যাই হোক, স্বচ্ছ ছবি মানিয়ে যায়৤ সাদা বাক্সসহ ছবি স্লাইড নষ্ট করে৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবিটি পণ্যের ছবি হিসেবে ব্যবহার হবে৤ দোকানের পণ্যের ছবি স্বচ্ছ ব্যাকগ্রাউন্ডে থাকলে ক্রেতা পণ্যটি ভালোভাবে দেখেন৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবিটি সোশ্যাল মিডিয়ার প্রোফাইলে ব্যবহার হবে৤ প্রোফাইল ছবি গোলাকার হয়, আর স্বচ্ছ ছবি গোলাকার ফ্রেমে ভালো দেখায়৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবিটি ছাপা হবে৤ স্বচ্ছ ছবি ছাপায় ব্যাকগ্রাউন্ড ছাড়া আসে৤ সাদা ব্যাকগ্রাউন্ডের ছবি ছাপায় সাদা বাক্স তৈরি করে৤</p>\n<p>স্বচ্ছতা গুরুত্বপূর্ণ যখন ছবিটি ভিডিওতে ব্যবহার হবে৤ ভিডিওর উপর স্বচ্ছ লোগো বসালে লোগো ভিডিওর অংশ মনে হয়৤ সাদা বাক্সসহ লোগো ভিডিও নষ্ট করে৤</p>\n<h2 id=\"when-it-does-not-matter\">কখন স্বচ্ছতা গুরুত্বপূর্ণ নয়</h2>\n<p>ছবিতে স্বচ্ছতা দরকার হয় না৤ ছবি পুরো ফ্রেম ভরে থাকে৤</p>\n<p>সাদা ব্যাকগ্রাউন্ডের ছবিতেও স্বচ্ছতা দরকার হয় না৤</p>\n<p>ছাপার কাজে স্বচ্ছতা দরকার হয় না৤ কাগজে স্বচ্ছতা দেখা যায় না৤</p>\n<h2 id=\"converting-cannot-add-transparency\">কনভার্ট করলে স্বচ্ছতা তৈরি হয় না</h2>\n<p>JPG থেকে PNG-তে কনভার্ট করলে স্বচ্ছতা তৈরি হয় না৤ JPG-তে স্বচ্ছতা নেই৤</p>\n<p>সাদা ব্যাকগ্রাউন্ড PNG-তে গেলেও সাদাই থাকে৤ তা স্বচ্ছ হয় না৤</p>\n<p>স্বচ্ছতা পেতে হলে সম্পাদনায় সাদা অংশ মুছে ফেলতে হয়৤ তারপর PNG-তে সংরক্ষণ করতে হয়৤</p>\n<h2 id=\"file-size-compared\">ফাইলের আকারের তুলনা</h2>\n<p>একই ছবি JPG-তে 200KB, PNG-তে 1MB হতে পারে৤</p>\n<p>স্বচ্ছ PNG ফাইল আরও বড় হয়৤ স্বচ্ছতার তথ্য জায়গা নেয়৤</p>\n<p>তবে লোগোর মতো ছোট ছবিতে পার্থক্য কম হয়৤ লোগো PNG-তেও ছোট থাকে৤</p>\n<h2 id=\"text-and-sharpness\">লেখা আর তীক্ষ্ণতা</h2>\n<p>PNG-তে লেখা সবচেয়ে পরিষ্কার থাকে৤ প্রান্ত তীক্ষ্ণ থাকে৤</p>\n<p>JPG-তে লেখার চারপাশে হালো দেখা যেতে পারে৤ ছোট লেখা অস্পষ্ট হতে পারে৤</p>\n<p>লেখা থাকা ছবিতে PNG ব্যবহার করুন৤</p>\n<p>ফাইলের আকারের তুলনায় JPG সবসময় ছোট৤ একই ছবি JPG-তে ২০০KB, আর PNG-তে ১MB হতে পারে৤ আকারের পার্থক্য পাঁচ গুণ পর্যন্ত হতে পারে৤</p>\n<p>ফাইলের আকারের তুলনা করার সময় ছবির ধরন দেখুন৤ ছবিতে লেখা বেশি থাকলে পার্থক্য কম হয়৤ ছবিতে মানুষ থাকলে পার্থক্য বেশি হয়৤</p>\n<p>ফাইলের আকারের তুলনায় WebP JPG-এর চেয়েও ছোট৤ WebP একই ছবি ১৫০KB-তে দিতে পারে৤ আকারের জন্য WebP সেরা৤</p>\n<p>ফাইলের আকারের তুলনা করার সময় লোডের সময় মাপুন৤ ছোট ফাইলের পাতা দ্রুত লোড হয়৤ বড় ফাইলের পাতা ধীর হয়৤</p>\n<p>ফাইলের আকারের তুলনায় মোবাইল ডেটার খরচ দেখুন৤ বড় ফাইল মোবাইল ডেটা বেশি খরচ করে৤ ছোট ফাইল ডেটা বাঁচায়৤</p>\n<p>ফাইলের আকারের তুলনায় স্টোরেজের খরচ দেখুন৤ হাজারটি PNG ছবি ফোনের স্টোরেজ ভরে দেয়৤ হাজারটি JPG ছবি কম জায়গা নেয়৤</p>\n<p>ফাইলের আকারের তুলনা করার সময় মানের পার্থক্য দেখুন৤ ছোট ফাইলে মান কমতে পারে৤ তবে ২০০KB JPG-এর মান PNG-এর কাছাকাছি৤</p>\n<p>ফাইলের আকারের তুলনায় ছাপার মান দেখুন৤ ছাপায় PNG ভালো৤ স্ক্রিনে দেখার জন্য JPG যথেষ্ট৤ ব্যবহার অনুযায়ী ফরম্যাট বেছে নিন৤</p>\n<p>ফাইলের আকারের তুলনা করে সিদ্ধান্ত নিন৤ আকার আর মানের ভারসাম্য দেখুন৤ শুধু আকার দেখে সিদ্ধান্ত নেবেন না৤</p>\n<h2 id=\"photos-compared\">ছবির তুলনা</h2>\n<p>ছবিতে JPG ভালো৤ ফাইল ছোট থাকে, আর মান ভালো থাকে৤</p>\n<p>ছবিতে PNG ব্যবহার করলে ফাইল অযথা বড় হয়৤ মান বাড়ে না৤</p>\n<p>ছবিতে স্বচ্ছতা দরকার হয় না৤ তাই JPG-ই সেরা৤</p>\n<h2 id=\"choosing-for-web\">ওয়েবসাইটের জন্য বেছে নেওয়া</h2>\n<p>ওয়েবসাইটের ছবির জন্য JPG বা WebP ব্যবহার করুন৤ ফাইল ছোট হয়৤</p>\n<p>লোগো আর আইকনের জন্য PNG ব্যবহার করুন৤ স্বচ্ছতা দরকার হয়৤</p>\n<p>WebP স্বচ্ছতাও দেয়, আবার ফাইল ছোট রাখে৤ আধুনিক ওয়েবসাইটে WebP ভালো৤</p>\n<h2 id=\"choosing-for-print\">ছাপার জন্য বেছে নেওয়া</h2>\n<p>ছাপার জন্য PNG ভালো৤ মান একদম ঠিক থাকে৤</p>\n<p>ছাপায় স্বচ্ছতা দরকার হয় না৤ কাগজে স্বচ্ছতা দেখা যায় না৤</p>\n<p>ছাপার জন্য উচ্চ মানের JPG-ও ভালো৤ ফাইল ছোট থাকে৤</p>\n<h2 id=\"practical-rule\">বাস্তব নিয়ম</h2>\n<p>ছবি হলে JPG৤ লোগো হলে PNG৤ এই নিয়ম মনে রাখুন৤</p>\n<p>স্বচ্ছতা দরকার হলে PNG৤ স্বচ্ছতা না দরকার হলে JPG৤</p>\n<p>অনিশ্চিত হলে PNG নিন৤ এটি সব জায়গায় চলে৤</p>\n<p>বাস্তব নিয়ম হলো ছবির ব্যবহার দেখে ফরম্যাট বেছে নেওয়া৤ ছবি দেখানোর জন্য JPG, আর সম্পাদনার জন্য PNG৤ ব্যবহার না জেনে ফরম্যাট বেছে নিলে ভুল হয়৤</p>\n<p>বাস্তব নিয়ম হলো স্বচ্ছতা দরকার হলে PNG, না হলে JPG৤ স্বচ্ছতা ছাড়া PNG-তে ফাইল বড় হয়৤ স্বচ্ছতা না থাকলে JPG যথেষ্ট৤</p>\n<p>বাস্তব নিয়ম হলো লেখা বেশি থাকলে PNG, ছবি বেশি থাকলে JPG৤ লেখা PNG-তে পরিষ্কার থাকে৤ ছবি JPG-তে ছোট হয়৤</p>\n<p>বাস্তব নিয়ম হলো ওয়েবসাইটে WebP, আর পোর্টালে JPG৤ WebP ওয়েবে দ্রুত লোড হয়৤ পোর্টালে WebP নাও চলতে পারে৤</p>\n<p>বাস্তব নিয়ম হলো মূল ফাইল সংরক্ষণ করা৤ মূল থাকলে যেকোনো ফরম্যাটে আবার তৈরি করা যায়৤ মূল ছাড়া ফরম্যাট বদলানো ঝুঁকিপূর্ণ৤</p>\n<p>বাস্তব নিয়ম হলো প্রিভিউ দেখে সিদ্ধান্ত নেওয়া৤ সংখ্যার চেয়ে চোখের বিচার ভালো৤ প্রিভিউতে ছবি ভালো লাগলে ফরম্যাট ঠিক আছে৤</p>\n<p>বাস্তব নিয়ম হলো ফাইলের আকারের চেয়ে মানকে গুরুত্ব দেওয়া৤ ছোট ফাইল ভালো, তবে ছবি অস্পষ্ট হলে তা কোনো কাজে আসে না৤</p>\n<p>বাস্তব নিয়ম হলো দলের মানদণ্ড মেনে চলা৤ দলের সবাই একই নিয়মে ফরম্যাট বেছে নিলে ছবি একরকম থাকে৤</p>\n<p>বাস্তব নিয়ম হলো পরীক্ষা করা৤ একই ছবি দুটি ফরম্যাটে তৈরি করে তুলনা করুন৤ তুলনা করে সিদ্ধান্ত নিন৤</p>\n<h2 id=\"logos-dark-backgrounds\">গাঢ় ব্যাকগ্রাউন্ডে লোগো</h2>\n<p>গাঢ় ব্যাকগ্রাউন্ডে সাদা লোগো বসাতে স্বচ্ছ PNG ব্যবহার করুন৤</p>\n<p>JPG লোগোতে সাদা বাক্স দেখা যায়৤ এটি খারাপ দেখায়৤</p>\n<p>স্বচ্ছ PNG লোগো যেকোনো ব্যাকগ্রাউন্ডে ভালো দেখায়৤</p>\n<h2 id=\"icons-apps-websites\">আইকন, অ্যাপ আর ওয়েবসাইট</h2>\n<p>আইকনে স্বচ্ছতা দরকার৤ PNG আইকন যেকোনো জায়গায় বসানো যায়৤</p>\n<p>অ্যাপের আইকনে PNG ব্যবহার করুন৤ এতে প্রান্ত তীক্ষ্ণ থাকে৤</p>\n<p>ওয়েবসাইটের আইকনে SVG বা PNG ব্যবহার করুন৤ দুটোই ভালো৤</p>\n<h2 id=\"stickers-social-graphics\">স্টিকার আর সোশ্যাল গ্রাফিক্স</h2>\n<p>স্টিকারে স্বচ্ছতা দরকার৤ PNG স্টিকার যেকোনো ছবির উপর বসানো যায়৤</p>\n<p>সোশ্যাল মিডিয়ার গ্রাফিক্সে PNG ব্যবহার করুন৤ লেখা তীক্ষ্ণ থাকে৤</p>\n<p>স্টিকার বানাতে ছবির ব্যাকগ্রাউন্ড মুছে PNG-তে সংরক্ষণ করুন৤</p>\n<p>স্টিকার সোশ্যাল গ্রাফিক্সে স্বচ্ছ ব্যাকগ্রাউন্ড থাকা উচিত৤ স্বচ্ছ স্টিকার যেকোনো ছবির উপর বসানো যায়৤ সাদা বাক্সসহ স্টিকার খারাপ দেখায়৤</p>\n<p>স্টিকার তৈরি করতে PNG ব্যবহার করুন৤ PNG-তে স্বচ্ছতা থাকে৤ JPG-তে স্বচ্ছতা থাকে না৤</p>\n<p>স্টিকার ছোট রাখুন৤ ছোট স্টিকার চ্যাটে দ্রুত লোড হয়৤ বড় স্টিকার চ্যাট ধীর করে৤</p>\n<p>স্টিকার শেয়ার করার আগে প্রিভিউ দেখুন৤ প্রিভিউতে স্টিকার কেমন দেখায় তা দেখা যায়৤ স্টিকার খারাপ লাগলে আবার তৈরি করুন৤</p>\n<p>স্টিকারের রং উজ্জ্বল রাখুন৤ উজ্জ্বল স্টিকার চ্যাটে চোখে পড়ে৤ ফিকে স্টিকার দেখা যায় না৤</p>\n<p>স্টিকার সোশ্যাল মিডিয়ায় পোস্ট করার সময় প্ল্যাটফর্মের নিয়ম দেখুন৤ কিছু প্ল্যাটফর্ম স্টিকারের আকার সীমিত করে৤</p>\n<p>স্টিকারের সংগ্রহ রাখুন৤ প্রিয় স্টিকারগুলো একটি ফোল্ডারে রাখুন৤ দরকারের সময় দ্রুত পাওয়া যায়৤</p>\n<p>স্টিকার নিজে তৈরি করতে পারেন৤ নিজের ছবি দিয়ে স্টিকার বানান৤ ব্যক্তিগত স্টিকার চ্যাটে বেশি মজার হয়৤</p>\n<p>স্টিকার ব্যবহার করার সময় প্রসঙ্গ দেখুন৤ গম্ভীর আলোচনায় মজার স্টিকার পাঠাবেন না৤ প্রসঙ্গ অনুযায়ী স্টিকার বেছে নিন৤</p>\n<h2 id=\"watermarks-overlays\">ওয়াটারমার্ক আর ওভারলে</h2>\n<p>ওয়াটারমার্কে স্বচ্ছতা দরকার৤ স্বচ্ছ PNG ওয়াটারমার্ক ছবির উপর হালকাভাবে বসে৤</p>\n<p>JPG ওয়াটারমার্কে সাদা বাক্স দেখা যায়৤ এটি খারাপ দেখায়৤</p>\n<p>ওভারলেতে PNG ব্যবহার করুন৤ এতে মূল ছবি ঢাকা পড়ে না৤</p>\n<h2 id=\"choosing-format-new-project\">নতুন প্রজেক্টের জন্য ফরম্যাট বেছে নেওয়া</h2>\n<p>নতুন প্রজেক্টে ছবির জন্য JPG, লোগোর জন্য PNG বেছে নিন৤</p>\n<p>ওয়েবসাইটের জন্য WebP ভাবুন৤ এটি ছোট ফাইল দেয় আর স্বচ্ছতাও দেয়৤</p>\n<p>প্রজেক্টের শুরুতে ফরম্যাট ঠিক করুন৤ পরে বদলাতে সময় নষ্ট হয়৤</p>\n<p>ধাপে ধাপে পদ্ধতির জন্য দেখুন <a href=\"/bn/blog/jpg-to-png-kivabe-korben\">JPG থেকে PNG করবেন কীভাবে</a> আর পূর্ণ গাইডের জন্য <a href=\"/bn/blog/jpg-to-png-guide\">JPG থেকে PNG গাইড</a>৤ PNG থেকে JPG করতে <a href=\"/bn/blog/png-to-jpg-guide\">PNG থেকে JPG গাইড</a> পড়ুন৤ কনভার্ট করতে <a href=\"/bn/jpg-to-png\">JPG থেকে PNG টুল</a> আর <a href=\"/bn/png-to-jpg\">PNG থেকে JPG টুল</a> ব্যবহার করুন৤</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"JPG কি স্বচ্ছতা দিতে পারে?","answer":"না৤ JPG স্বচ্ছতা দিতে পারে না৤ প্রতিটি পিক্সেলে রং থাকতে হয়৤ স্বচ্ছতা দরকার হলে PNG বা WebP ব্যবহার করুন৤"},{"question":"JPG থেকে PNG-তে কনভার্ট করলে কি স্বচ্ছতা তৈরি হয়?","answer":"না৤ JPG-তে স্বচ্ছতা নেই, তাই PNG-তে কনভার্ট করলেও স্বচ্ছতা তৈরি হয় না৤ সাদা ব্যাকগ্রাউন্ড PNG-তে গেলেও সাদাই থাকে৤ স্বচ্ছতা পেতে সম্পাদনায় সাদা অংশ মুছে ফেলতে হয়৤"},{"question":"লোগোর জন্য কোন ফরম্যাট ভালো?","answer":"PNG ভালো৤ PNG স্বচ্ছতা দেয়, তাই লোগো যেকোনো ব্যাকগ্রাউন্ডে বসানো যায়৤ JPG লোগোতে সাদা বাক্স দেখা যায়৤ WebP-ও স্বচ্ছতা দেয়, তবে সব জায়গায় চলে না৤"},{"question":"ছবির জন্য JPG না PNG?","answer":"ছবির জন্য JPG ভালো৤ ফাইল ছোট থাকে, আর মান ভালো থাকে৤ ছবিতে PNG ব্যবহার করলে ফাইল অযথা বড় হয়৤ ছবিতে স্বচ্ছতা দরকার হয় না৤"},{"question":"ওয়েবসাইটে স্বচ্ছ ছবির জন্য কী ব্যবহার করব?","answer":"PNG বা WebP ব্যবহার করুন৤ WebP স্বচ্ছতাও দেয়, আবার ফাইল ছোট রাখে৤ পুরোনো ব্রাউজারের জন্য PNG ফলব্যাক রাখুন৤"},{"question":"ওয়াটারমার্কের জন্য কোন ফরম্যাট ভালো?","answer":"স্বচ্ছ PNG ভালো৤ স্বচ্ছ PNG ওয়াটারমার্ক ছবির উপর হালকাভাবে বসে৤ JPG ওয়াটারমার্কে সাদা বাক্স দেখা যায়৤"}];
